#!/usr/bin/env python3
"""Generate .github/workflows/s2arm-delivery.yml from the standard delivery workflow.

The Switch 2 (S2Arm) test IPA is built by the same jobs and steps as the common IPA. This script
derives its workflow from .github/workflows/standard-delivery.yml with the changes listed in CHANGES
and nothing else, so the difference between the two workflows is explicit and reproducible:

    python3 -B .github/diagnostics/s2arm/make_workflow.py            write the workflow
    python3 -B .github/diagnostics/s2arm/make_workflow.py --check    fail unless the committed file is current
    python3 -B .github/diagnostics/s2arm/make_workflow.py --explain  print the differences as data

Every edit names the exact text it replaces and how often it must occur; a standard workflow that
no longer matches stops the generation instead of producing an approximate copy.
"""
from __future__ import annotations

import argparse
import json
from pathlib import Path
import sys

ROOT = Path(__file__).resolve().parents[3]
sys.path.insert(0, str(Path(__file__).resolve().parent))

import standard_delivery_s2arm as line  # noqa: E402

SOURCE = line.COMMON_WORKFLOW
TARGET = line.WORKFLOW
COMMON_CALL = 'python3 -B .github/diagnostics/standard_delivery.py '
LINE_CALL = 'python3 -B .github/diagnostics/s2arm/standard_delivery_s2arm.py '
PROBE = 'python3 build-utils/s2arm/set_probe_key.py '
APP = 'build/ios/DolphinDerivedData/Build/Products/Release-iphoneos/Runner.app'
PROTECTED_UPLOAD = ('TarbleFR/RewindBox/.github/actions/upload-protected-artifact@'
                    '3bd75a37a4056eb9324987c76f32b002a89d58cb')

HEADER_COMMON = '''# Standard private IPA delivery (AGENTS.md "Same recipe for every build").
# One workflow for every build: the build number, recipient and artifact names come from the
# preflight outputs, which read build-utils/delivery/<N>.json named by the commit subject tag.
# A push whose subject has no delivery tag runs nothing (every job is skipped).
# Every job that reads product files restores the frozen effective tree first (materialize)
# and never checks out again. The application job does not wait for the test jobs to build;
# it authenticates them (await-tests) right before embedding the test identity and sealing.
name: RewindBox standard private IPA delivery
run-name: RewindBox standard delivery - ${{ github.sha }}
'''
HEADER_LINE = f'''# GENERATED by .github/diagnostics/s2arm/make_workflow.py from {SOURCE}.
# Do not edit: change the generator, regenerate, and keep the --check of the test green.
#
# Private test IPA of the Switch 2 (S2Arm) line (builds from {line.FIRST_BUILD}): the standard delivery
# recipe, unchanged, run through its launcher .github/diagnostics/s2arm/standard_delivery_s2arm.py.
# Same jobs, steps, validators, encryption to the recipient key and transport split as the common
# workflow. Differences: the trigger (this branch only, subject tag {line.TRIGGER_MARKER}N], or a manual
# run naming the same build), the request and recipient guards, the Info.plist probe key set between
# the generated host and the version stamp, and the probe checks on the built and on the signed
# application. A push whose subject has no delivery tag runs nothing (every job is skipped).
name: RewindBox Switch 2 test IPA delivery
run-name: RewindBox Switch 2 test delivery - ${{{{ github.sha }}}}
'''

TRIGGER_COMMON = """'on':
  push:
    branches:
    - Claude
"""
TRIGGER_LINE = f"""'on':
  push:
    branches:
    - {line.DELIVERY_BRANCH}
  workflow_dispatch:
    inputs:
      build:
        description: Build of the Switch 2 test line that the head commit subject requests (801 or later)
        required: true
        type: string
"""

GATE_COMMON = ("    if: ${{ github.ref == 'refs/heads/Claude' && "
               "startsWith(github.event.head_commit.message, '[ipa-delivery:') }}\n")
GATE_LINE = (f"    if: ${{{{ github.ref == 'refs/heads/{line.DELIVERY_BRANCH}' && "
             "(github.event_name == 'workflow_dispatch' || "
             f"startsWith(github.event.head_commit.message, '{line.TRIGGER_MARKER}')) }}}}\n")

# (old text, new text, exact number of occurrences in the standard workflow)
REPLACEMENTS = (
    (HEADER_COMMON, HEADER_LINE, 1),
    (TRIGGER_COMMON, TRIGGER_LINE, 1),
    ('  group: rewindbox-ipa-delivery-${{ github.ref }}\n', '  group: rewindbox-s2arm-delivery-${{ github.ref }}\n', 1),
    (GATE_COMMON, GATE_LINE, 1),
    (COMMON_CALL, LINE_CALL, 37),
)

REQUEST_GUARD = f'''    - name: Check that this run requests a build of the Switch 2 test line
      if: ${{{{ steps.manifest.outputs.build != '' }}}}
      env:
        REQUESTED_BUILD: ${{{{ inputs.build }}}}
      run: {LINE_CALL}request-guard
'''
RECIPIENT_GUARD_PREFLIGHT = f'''    - name: Check the committed recipient public key of this build
      if: ${{{{ steps.manifest.outputs.build != '' }}}}
      env:
        BUILD_NUMBER: ${{{{ steps.manifest.outputs.build }}}}
        DELIVERY_RECIPIENT: ${{{{ steps.manifest.outputs.recipient }}}}
      run: {LINE_CALL}recipient-guard
'''
RECIPIENT_GUARD_APPLICATION = f'''    - name: Check the committed recipient public key of this build
      run: {LINE_CALL}recipient-guard
'''
PROBE_KEY = f'''    - name: Turn the S2Arm device probe on in the generated host
      run: |
        {PROBE}set
        {PROBE}check-host
'''
PROBE_APP = f'''    - name: Check the S2Arm probe key and code in the compiled application
      run: {PROBE}check-app {APP} --report build/delivery/s2arm-probe-app.json
'''
PROBE_IPA = f'''    - name: Check the S2Arm probe key and code in the signed IPA
      run: {PROBE}check-ipa "dist/$IPA_NAME.ipa" --report build/delivery/s2arm-probe-ipa.json
'''
# (job, existing step the new step follows, new step)
INSERTIONS = (
    ('preflight', 'Materialize the frozen effective product tree', REQUEST_GUARD),
    ('preflight', 'Check that this run requests a build of the Switch 2 test line', RECIPIENT_GUARD_PREFLIGHT),
    ('application', 'Materialize the frozen effective product tree', RECIPIENT_GUARD_APPLICATION),
    ('application', 'Verify central session pod is in the actual generated host', PROBE_KEY),
    ('application', 'Compile Release device binary with measured AOT and Xcode phases', PROBE_APP),
    ('application', 'Verify every signed image, the replaced Core payloads and the retained payloads', PROBE_IPA),
)
# The step each inserted step must precede (order asserted on the generated workflow).
ORDER = (
    ('application', 'Generate iOS host', 'Turn the S2Arm device probe on in the generated host'),
    ('application', 'Configure release host', 'Turn the S2Arm device probe on in the generated host'),
    ('application', 'Turn the S2Arm device probe on in the generated host',
     'Align application and extension versions to the pubspec version'),
    ('application', 'Align application and extension versions to the pubspec version',
     'Compile Release device binary with measured AOT and Xcode phases'),
    ('application', 'Compile Release device binary with measured AOT and Xcode phases',
     'Check the S2Arm probe key and code in the compiled application'),
    ('application', 'Check the S2Arm probe key and code in the signed IPA', 'Prepare encrypted delivery and evidence'),
    ('preflight', 'Check the committed recipient public key of this build', 'Run the delivery contract'),
)


class GenerationError(ValueError):
    pass


def require(condition, message):
    if not condition:
        raise GenerationError(message)


def job_span(lines, job):
    """[start, end) line indexes of one job of the workflow text."""
    start = [i for i, text in enumerate(lines) if text == f'  {job}:']
    require(len(start) == 1, f'Job {job} not found exactly once')
    end = next((i for i in range(start[0] + 1, len(lines))
                if lines[i].startswith('  ') and not lines[i].startswith('   ') and lines[i].strip()), len(lines))
    return start[0], end


def insert_after(text, job, after, step):
    lines = text.split('\n')
    start, end = job_span(lines, job)
    found = [i for i in range(start, end) if lines[i] == f'    - name: {after}']
    require(len(found) == 1, f'Step {after!r} not found exactly once in job {job}')
    following = next((i for i in range(found[0] + 1, end) if lines[i].startswith('    - ')), end)
    return '\n'.join(lines[:following] + step.rstrip('\n').split('\n') + lines[following:])


def generate(source_text):
    text = source_text
    for old, new, count in REPLACEMENTS:
        require(text.count(old) == count, f'Expected {count} occurrence(s) of {old.splitlines()[0]!r} in the standard '
                f'workflow, found {text.count(old)}')
        text = text.replace(old, new)
    require('standard_delivery.py' not in text and 'ipa-delivery' not in text and "'refs/heads/Claude'" not in text,
            'A reference to the common line remains in the generated workflow')
    for job, after, step in INSERTIONS:
        text = insert_after(text, job, after, step)
    return text


def step_names(spec, job):
    return [step.get('name') for step in spec['jobs'][job]['steps']]


def explain(source_text, target_text, load):
    """The differences between the two parsed workflows, checked to be exactly the declared ones."""
    common, generated = load(source_text), load(target_text)
    require(list(common['jobs']) == list(generated['jobs']), 'The jobs differ')
    inserted = {}
    for job in common['jobs']:
        before, after = step_names(common, job), step_names(generated, job)
        added = [name for name in after if name not in before]
        require([name for name in after if name in before] == before, f'Steps of {job} were removed or reordered')
        require(added == [step.split('\n')[0].removeprefix('    - name: ') for j, _, step in INSERTIONS if j == job],
                f'Unexpected inserted steps in {job}: {added}')
        inserted[job] = added
        kept = {step['name']: step for step in generated['jobs'][job]['steps']}
        for step in common['jobs'][job]['steps']:
            expected = json.loads(json.dumps(step).replace(COMMON_CALL, LINE_CALL))
            require(kept[step['name']] == expected, f'Step {step["name"]!r} of {job} differs beyond the launcher call')
        for key in common['jobs'][job]:
            if key not in ('steps', 'if') or (key == 'if' and job != 'preflight'):
                require(common['jobs'][job][key] == generated['jobs'][job][key], f'{job}.{key} differs')
    for job, first, second in ORDER:
        names = step_names(generated, job)
        require(names.index(first) < names.index(second), f'{first!r} must precede {second!r} in {job}')
    uploads = [step['uses'] for job in generated['jobs'].values() for step in job['steps']
               if 'upload' in step.get('uses', '')]
    require(uploads and set(uploads) == {PROTECTED_UPLOAD}, 'An upload does not use the protected action at its pin')
    trigger = generated.get('on', generated.get(True))
    require(set(trigger) == {'push', 'workflow_dispatch'} and trigger['push'] == {'branches': [line.DELIVERY_BRANCH]} and
            trigger['workflow_dispatch']['inputs']['build']['required'] is True, 'Unexpected trigger')
    for key in ('permissions', 'env'):
        require(common[key] == generated[key], key + ' differs')
    return dict(source=SOURCE, target=TARGET, jobs=list(generated['jobs']), insertedSteps=inserted,
                launcherCalls=target_text.count(LINE_CALL), uploads=len(uploads), trigger=trigger,
                preflightGate=generated['jobs']['preflight']['if'], concurrency=generated['concurrency'])


def main(argv=None):
    parser = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    parser.add_argument('--check', action='store_true')
    parser.add_argument('--explain', action='store_true')
    args = parser.parse_args(argv)
    source_text = (ROOT / SOURCE).read_text()
    text = generate(source_text)
    report = explain(source_text, text, line.load_recipe().load_yaml_subset)
    target = ROOT / TARGET
    if args.check:
        if not target.is_file() or target.read_text() != text:
            print(f'{TARGET} is not the workflow generated from {SOURCE}; regenerate it', file=sys.stderr)
            return 1
    elif not args.explain:
        target.write_text(text)
    print(json.dumps(report, indent=2))
    return 0


if __name__ == '__main__':
    raise SystemExit(main())
